/** Convert create form state into the payload that baseBranchCreateSchema accepts. */
export function buildBranchCreatePayload(form: BranchCreateFormState): BaseBranchCreate {
  const payload: Record<string, unknown> = {
    console_branch_id: form.console_branch_id.trim(),
    console_organization_id: form.console_organization_id.trim(),
    code: form.code?.toString().trim() || null,
    slug: form.slug.trim(),
    name: (form.name["ja"] ?? '').trim(),
    is_headquarters: form.is_headquarters,
    is_active: form.is_active,
    faq_inherit_hq: form.faq_inherit_hq,
    timezone: form.timezone?.toString().trim() || null,
    currency: form.currency?.toString().trim() || null,
    locale: form.locale?.toString().trim() || null,
    console_brand_id: form.console_brand_id?.toString().trim() || null,
    invoice_prefix: form.invoice_prefix?.toString().trim() || null,
    invoice_registration_number: form.invoice_registration_number?.toString().trim() || null,
    address: form.address?.toString().trim() || null,
    phone: form.phone?.toString().trim() || null,
    img_branches: form.img_branches?.toString().trim() || null,
    banner_desktop: form.banner_desktop?.toString().trim() || null,
    banner_tablet: form.banner_tablet?.toString().trim() || null,
    banner_mobile: form.banner_mobile?.toString().trim() || null,
    logo: form.logo?.toString().trim() || null,
    seat_capacity: form.seat_capacity,
    business_hours: form.business_hours?.toString().trim() || null,
    weekly_hours: form.weekly_hours,
    cart_timeout_minutes: form.cart_timeout_minutes,
    takeaway_payment_timeout_minutes: form.takeaway_payment_timeout_minutes,
    point_earn_amount: form.point_earn_amount,
    point_earn_points: form.point_earn_points,
    review_avg_rating: form.review_avg_rating,
    review_total_count: form.review_total_count,
  };

  // Per-locale sub-objects (matches issue #53 wire shape).
  const i18n = buildI18nPayload({
    name: form.name,
  });
  Object.assign(payload, i18n);

  return payload as BaseBranchCreate;
}

